H.background();
const cx = H.W*0.5, cy = H.H*0.55, R = 150;
// point on circle controlled by slider P.ang (degrees), gently nudged by t
const a = P.ang*Math.PI/180 + 0.15*Math.sin(t*0.7);
const Tx = cx + R*Math.cos(a), Ty = cy + R*Math.sin(a);
// tangent direction is perpendicular to radius: (-sin, cos)
const tx = -Math.sin(a), ty = Math.cos(a);
const L = 150;
const T1x = Tx - tx*L, T1y = Ty - ty*L;
const T2x = Tx + tx*L, T2y = Ty + ty*L;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
// radius
H.line(cx, cy, Tx, Ty, { color: H.colors.accent, width: 2.5 });
// tangent line
H.line(T1x, T1y, T2x, T2y, { color: H.colors.accent2, width: 3 });
// right-angle square at T
const s = 16;
const rx = -Math.cos(a), ry = -Math.sin(a); // inward radial dir
const c1 = [Tx + rx*s, Ty + ry*s];
const c2 = [c1[0] + tx*s, c1[1] + ty*s];
const c3 = [Tx + tx*s, Ty + ty*s];
H.path([[Tx,Ty], c3, c2, c1], { color: H.colors.good, width: 2, close: true });
H.circle(Tx, Ty, 6, { fill: H.colors.yellow });
H.text("Tangent is perpendicular to the radius", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("The radius (blue) meets the tangent (orange) at exactly 90 deg.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("touch point angle = " + (((P.ang%360)+360)%360).toFixed(0) + " deg", 24, 80, { color: H.colors.yellow, size: 14 });
H.text("radius . tangent = 0  ->  angle = 90 deg", 24, 100, { color: H.colors.good, size: 14 });
